import{_ as n,C as r,o as i,c as o,ag as e,E as a}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"Seller Subscriptions","description":"","frontmatter":{},"headers":[],"relativePath":"subscriptions/seller-subscription-management.md","filePath":"subscriptions/seller-subscription-management.md","lastUpdated":1787558413000}'),l={name:"subscriptions/seller-subscription-management.md"};function c(p,s,g,u,d,m){const t=r("ImagePopup");return i(),o("div",null,[s[0]||(s[0]=e('<h1 id="seller-subscriptions" tabindex="-1">Seller Subscriptions <a class="header-anchor" href="#seller-subscriptions" aria-label="Permalink to &quot;Seller Subscriptions&quot;">​</a></h1><p>Seller Subscriptions let the marketplace charge sellers a recurring fee to sell, using <strong>plans</strong> that can bundle their own commission rate, product and staff limits, and permissions. It&#39;s an <strong>optional</strong> feature — off by default — that the admin turns on when they want a subscription-based model.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to enable subscriptions</li><li>Everything a plan defines</li><li>How sellers subscribe, and the subscription lifecycle</li></ul></div><h2 id="enabling-subscriptions" tabindex="-1">Enabling subscriptions <a class="header-anchor" href="#enabling-subscriptions" aria-label="Permalink to &quot;Enabling subscriptions&quot;">​</a></h2><p>Subscriptions are disabled until the admin switches them on. Go to <strong>Configure → Marketplace → General</strong>, enable <strong>Subscription Plans</strong>, and set the <strong>subscription terms</strong> sellers must agree to. Until this is on, the plans area isn&#39;t available.</p>',5)),a(t,{src:"/images/seller-subscription-management/subscription-settings.png",alt:"Marketplace settings with the subscription switch"}),s[1]||(s[1]=e('<h2 id="plans" tabindex="-1">Plans <a class="header-anchor" href="#plans" aria-label="Permalink to &quot;Plans&quot;">​</a></h2><p>Once enabled, the admin manages plans under <strong>Marketplace → Subscription Plans → Plans</strong>, where each plan can be created, edited, enabled, or reordered. A plan defines:</p><ul><li><strong>Name</strong>, <strong>code</strong>, and <strong>description</strong>, and whether it&#39;s the <strong>default</strong> (free) plan.</li><li><strong>Price</strong> and <strong>billing cycle</strong> (<strong>monthly</strong> or <strong>yearly</strong>), with an optional custom <strong>duration</strong> in days.</li><li><strong>Max Products</strong> and <strong>Max Staff</strong> the seller may have (empty means unlimited).</li><li><strong>Commission Value</strong> — the commission rate that applies to a seller on this plan.</li><li><strong>Permissions</strong> — either <strong>all</strong> access or a <strong>custom</strong> set from the seller permission tree.</li><li><strong>Allowed Product Types</strong>, <strong>featured</strong> flag, <strong>status</strong>, and <strong>position</strong>.</li></ul><h2 id="subscribing-seller" tabindex="-1">Subscribing (seller) <a class="header-anchor" href="#subscribing-seller" aria-label="Permalink to &quot;Subscribing (seller)&quot;">​</a></h2><p>With subscriptions on, a seller browses the <strong>available plans</strong> in their panel — each card shows the price, duration, product/staff limits, commission, and the permissions it grants. Choosing one opens a summary, requires agreeing to the <strong>terms</strong>, and then takes payment (free/default plans activate immediately; paid plans go through a payment gateway). Sellers can see their <strong>subscription history</strong> too.</p><h2 id="the-subscription-lifecycle" tabindex="-1">The subscription lifecycle <a class="header-anchor" href="#the-subscription-lifecycle" aria-label="Permalink to &quot;The subscription lifecycle&quot;">​</a></h2><ul><li>A new subscription starts <strong>pending</strong>, becomes <strong>active</strong> on successful payment (or immediately for a free plan), and later moves to <strong>expired</strong> or <strong>cancelled</strong>. Statuses are <strong>pending / active / expired / cancelled</strong>.</li><li>When a subscription activates, the seller&#39;s <strong>commission</strong>, <strong>allowed product types</strong>, <strong>product limit</strong>, and <strong>staff limit</strong> follow the plan. If a plan&#39;s product limit is exceeded, the newest products beyond the limit are disabled until the seller is within limits again.</li><li>The admin reviews who&#39;s subscribed under <strong>Marketplace → Subscription Plans → Subscription</strong>, and can <strong>approve</strong> or <strong>cancel</strong> subscriptions. Sellers are reminded before a subscription expires, and expired subscriptions are closed automatically.</li></ul><div class="info custom-block"><p class="custom-block-title">Commission-only marketplaces</p><p>If you&#39;d rather not charge a recurring fee, simply leave subscriptions off — sellers then sell without a subscription and you earn purely through <a href="/payments/commission-management">commission</a>.</p></div>',8))])}const f=n(l,[["render",c]]);export{b as __pageData,f as default};
